47	    /// Runs one command line (without its newline) and returns the response
48	    /// line (without its newline).
49	    pub fn handle_line(&mut self, line: &[u8]) -> String {
50	        let response = match Request::parse(line).and_then(|req| self.dispatch(&req)) {
51	            Ok(mut members) => {
52	                members.insert("ok".into(), Value::Bool(true));
53	                Value::Object(members)
54	            }
55	            Err(Error { code, message }) => json!({
56	                "ok": false,
57	                "error": { "code": code.as_str(), "message": message },
58	            }),
59	        };
60	        response.to_string()
61	    }
62	
63	    fn dispatch(&mut self, req: &Request) -> Result<Members> {
64	        let params = req.params();
65	        match req.command.as_str() {
66	            "CreateQueue" => self.create_queue(params),
67	            "SetQueueAttributes" => self.set_queue_attributes(params),
68	            "GetQueueAttributes" => self.get_queue_attributes(params),
69	            "ListQueues" => self.list_queues(params),
70	            "DeleteQueue" => self.delete_queue(params),
71	            "PurgeQueue" => self.purge_queue(params),
72	            "SendMessage" => self.send_message(params),
73	            "ReceiveMessage" => self.receive_message(params),
74	            "DeleteMessage" => self.delete_message(params),
75	            "ChangeMessageVisibility" => self.change_message_visibility(params),
76	            "Tick" => self.tick(params),
77	            other => Err(Error::new(
78	                ErrorCode::InvalidRequest,
79	                format!("unknown command `{other}`"),
80	            )),
81	        }
82	    }
83	
84	    fn tick(&mut self, params: Params<'_>) -> Result<Members> {
85	        params.require(&["Seconds"])?;
86	        let seconds = params.integer("Seconds", 0..=MAX_TICK)?.expect("required");
87	        self.now += seconds;
88	        Ok(members([("Now", json!(self.now))]))
89	    }
90	
91	    /// Looks up a queue (SPEC section 2, check 4) with expired messages
92	    /// already removed.
93	    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
94	        lookup(&mut self.queues, self.now, name)
95	    }
